const cps=[0x01,0x09,0x0a,0x0b,0x0d,0x1f,0x20,0x7f,0x80,0x85,0x9f,0xa0,0xa1,0xad,0xe9,0x301,0x378,0x2007,0x200b,0x200d,0x2028,0x2029,0x2060,0x3000,0xe000,0xfeff,0x4e2d,0x10000,0x1f600,0xe0001,0xf0000];
const np=c=>(c>=0xD800&&c<=0xDFFF)|| (c!==0x20 && /\p{C}|\p{Z}/u.test(String.fromCodePoint(c)));
for(const c of cps) console.log("U+"+c.toString(16).padStart(4,"0").toUpperCase(), np(c)?"ESCAPE":"literal");
console.log("surrogate 0xDCFF ->", np(0xDCFF)?"ESCAPE":"literal");
'
